def listening(lid, part, script, items):
    group = f"{lid}-g{1 + len({q.get('group_id') for q in DATA['questions'] if q['lesson_id'] == lid}) :02d}"
    for prompt, choices, why in items:
        question(lid, part, prompt, choices, why, group_id=group, audio_id=group, transcript=script)


