def completion(lid, passage, items):
    group = f"{lid}-g{1 + len({q.get('group_id') for q in DATA['questions'] if q['lesson_id'] == lid}) :02d}"
    for number, (choices, why) in enumerate(items, 1):
        question(lid, 6, f"Choose the best option for blank [{number}].", choices, why, passage=passage, group_id=group)


